#include <bits/stdc++.h>
using namespace std;
int main(int argc,char**argv){string dir="/work/analyzebpe/r16/";string suffix=argv[1],next=argv[2];ifstream d(dir+"dict"+suffix+".bin",ios::binary);vector<string>dict;while(1){unsigned char len;d.read((char*)&len,1);if(!d)break;string s(len,'\0');d.read(s.data(),len);dict.push_back(s);}ifstream t(dir+"tokens"+suffix+".bin",ios::binary);t.seekg(0,ios::end);size_t n=t.tellg()/2;t.seekg(0);vector<uint16_t>tok(n);t.read((char*)tok.data(),n*2);vector<uint32_t>ct(dict.size());for(auto id:tok)ct[id]++;vector<pair<uint32_t,int>> keep;for(int i=256;i<(int)dict.size();i++)if(ct[i])keep.emplace_back(ct[i],i);sort(keep.begin(),keep.end(),greater<>());if(argc>3 && keep.size()>size_t(atoi(argv[3])-256))keep.resize(atoi(argv[3])-256); vector<bool> wanted(dict.size());for(int i=0;i<256;i++)wanted[i]=true;for(auto [count,id]:keep)wanted[id]=true;vector<string>nd;unordered_set<string>present;for(int i=0;i<(int)dict.size();i++)if(wanted[i]){nd.push_back(dict[i]);present.insert(dict[i]);}unordered_map<uint32_t,uint32_t>pc;pc.reserve(n/2);for(size_t i=0;i+1<n;i++)pc[(uint32_t(tok[i])<<16)|tok[i+1]]++;vector<pair<uint32_t,uint32_t>>ranks;for(auto[k,c]:pc)if(c>=2)ranks.emplace_back(c,k);sort(ranks.begin(),ranks.end(),greater<>());size_t orig=nd.size(),last=0;for(auto [cnt,key]:ranks){string s=dict[key>>16]+dict[key&65535];if(s.size()<=16 && present.insert(s).second){nd.push_back(s);last=cnt;}if(nd.size()>=65536)break;}ofstream out(dir+"dict"+next+".bin",ios::binary);size_t sz=0;for(auto&s:nd){uint8_t len=s.size();out.write((char*)&len,1);out.write(s.data(),len);sz+=len;}printf("used %zu added %zu dictbytes %zu lastfreq %zu\n",orig,nd.size()-orig,sz,last);}
